import unittest
import mock
from mock import patch
from taf.ul.oam.selenium_coam.pages.procedures import Procedures, ServiceAccountSshPage, ServiceAccountSshPageViewPanel


class TestProcedures(unittest.TestCase):
    @patch('taf.ul.oam.selenium_coam.common.common.CustomWebdriver')
    def setUp(self, mock_driver):
        mock_driver.return_value = mock.MagicMock()
        self.config = Procedures()


class TestServiceAccountSshPage(unittest.TestCase):
    @patch('taf.ul.oam.selenium_coam.common.common.WebDriver')
    def setUp(self, mock_driver):
        mock_driver.return_value = mock.MagicMock()
        self.service_account_ssh_page = ServiceAccountSshPage()

    def test_enable_ssh_service(self):
        self.service_account_ssh_page._view_panel.enable_ssh_service = mock.Mock()

        self.service_account_ssh_page.enable_ssh_service(60)
        self.service_account_ssh_page._view_panel.enable_ssh_service.assert_called_once()

    def test_disable_ssh_service(self):
        self.service_account_ssh_page._view_panel.disable_ssh_service = mock.Mock()

        self.service_account_ssh_page.disable_ssh_service(60)
        self.service_account_ssh_page._view_panel.disable_ssh_service.assert_called_once()


class TestServiceAccountSshPageViewPanel(unittest.TestCase):
    @patch('taf.ul.oam.selenium_coam.common.common.WebDriver')
    def setUp(self, mock_driver):
        mock_driver.return_value = mock.MagicMock()
        self.service_account_ssh_page_view_panel = ServiceAccountSshPageViewPanel()

    def test_enable_ssh_service(self):
        self.service_account_ssh_page_view_panel._check_current_ssh_service_status = mock.Mock(return_value="Disabled")
        self.service_account_ssh_page_view_panel._change_ssh_to_expected_status = mock.Mock()

        self.service_account_ssh_page_view_panel.enable_ssh_service()

        self.service_account_ssh_page_view_panel._check_current_ssh_service_status.assert_called_once()
        self.service_account_ssh_page_view_panel._change_ssh_to_expected_status.assert_called_once()

    def test_disable_ssh_service(self):
        self.service_account_ssh_page_view_panel._check_current_ssh_service_status = mock.Mock(return_value="Enabled")
        self.service_account_ssh_page_view_panel._change_ssh_to_expected_status = mock.Mock()

        self.service_account_ssh_page_view_panel.disable_ssh_service()

        self.service_account_ssh_page_view_panel._check_current_ssh_service_status.assert_called_once()
        self.service_account_ssh_page_view_panel._change_ssh_to_expected_status.assert_called_once()
